// $finish
    // creating block for making .vcd file
    initial begin
        $dumpfile("testbench.vcd");
        $dumpvars(1, class_top_tb);
    end

    always @(posedge tready) begin
        label = img_count / 96; // example label logic
        calc_label = output_params;
        if (label == calc_label)
            success = success + 1;
        else
            fail = fail + 1;

        // load next image (8 cycles)
        repeat (8) begin
            #10 load_next_chunk();
            x = x + 1;
        end
        #10
        x = 1;
    end

    // ----------------------------
    // Task: Load one 128-bit chunk
    // ----------------------------
    task load_next_chunk;
    begin
        // Read exactly 128 bits from file
        for (j = 0; j < 128; j = j + 1) begin
            r = $fgetc(fd);
            if (r == "0")
                total_img[127-j] = 1'b0;
            else if (r == "1")
                total_img[127-j] = 1'b1;
            else
                j = j - 1; // skip newline or junk
        end

        // Update cycle/image counters
        if (cycle_count == 7) begin
            cycle_count = 0;
            img_count   = img_count + 1;
        end
        else begin
            cycle_count = cycle_count + 1;
        end
    end
    endtask

endmodule

